def extract_products(html):
    soup = BeautifulSoup(html, "html.parser")
    products = []
    for li in soup.findAll("li", {"class": "col-xs-6 col-sm-4 col-md-3 col-lg-3"}):
        product = {}
        product["product_name"] = li.find("h3").text.strip()
        product["price"] = float(li.find("p", {"class": "price_color"}).text[1:])
        products.append(product)
    return products
